mapper.select:
/* LinkOrgMapper.selectLinkOrgList 조회 조건에 맞는 연계기관 목록을 기관ID 순으로 조회 (사용 가능 키 수 포함) */ SELECT O.LNK_ORG_ID, O.LNK_ORG_NM, O.CHNL_CLS_CD, O.USE_ST_DT, O.USE_END_DT, O.USE_YN, O.RMK, (SELECT COUNT(*) FROM TB_LNK_KEY_M K WHERE K.LNK_ORG_ID = O.LNK_ORG_ID AND K.KEY_STAT_CD = '01' AND (K.EXPI_DTTM IS NULL OR K.EXPI_DTTM > CURRENT_TIMESTAMP)) AS USE_KEY_CNT FROM TB_LNK_ORG_M O
AND (UPPER(O.LNK_ORG_ID) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(O.LNK_ORG_NM) LIKE '%' || UPPER(TRIM(#{keyword})) || '%')
AND O.CHNL_CLS_CD = #{chnlClsCd}
AND O.USE_YN = #{useYn}
ORDER BY O.LNK_ORG_ID

mapper.insert:
/* LinkOrgMapper.insertLinkOrg 연계기관을 등록 */
INSERT INTO TB_LNK_ORG_M (
    LNK_ORG_ID, LNK_ORG_NM, CHNL_CLS_CD, USE_ST_DT, USE_END_DT, USE_YN, RMK,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{item.lnkOrgId}, #{item.lnkOrgNm}, #{item.chnlClsCd}, NULLIF(#{item.useStDt}, ''), NULLIF(#{item.useEndDt}, ''),
    #{item.useYn}, NULLIF(#{item.rmk}, ''),
    #{usrId}, CURRENT_TIMESTAMP, #{usrId}, CURRENT_TIMESTAMP
)

mapper.update:
/* LinkOrgMapper.updateLinkOrgInterfaceUnused 목록에 없는 기존 허용 인터페이스를 사용 안 함(N)으로 수정 (행은 지우지 않음) */
UPDATE TB_LNK_ORG_INFC_R
   SET USE_YN       = 'N',
       FINA_REGR_ID = #{usrId},
       FINA_REG_DT  = CURRENT_TIMESTAMP
 WHERE LNK_ORG_ID = #{lnkOrgId}
   AND USE_YN = 'Y'

   AND INFC_ID NOT IN

        #{infcId}
